"""Build the bilingual advisory site. Run from the repository root.

The publish directory is explicit: only finished public assets are deployed.
Legacy publishing sites, local journals and source documents stay outside it.
"""
from pathlib import Path
from html import escape as e, unescape
import json, re, shutil, sys, argparse
sys.path.insert(0, str(Path(__file__).parent))
from advisory_content import CASES, DOMAINS, RESOURCES
from pages_data import PAGES
from articles_data import ARTICLES
from advisory_expertise import DETAILS
from advisory_translations import add_english
add_english(ARTICLES)

ROOT=Path(__file__).resolve().parent.parent
BASE='https://www.myxavier.finance'
OUT=ROOT/'dist-advisory'
BUILT={}
def t(lang,fr,en): return fr if lang=='fr' else en
def href(lang,path=''): return ('/fr/' if lang=='fr' else '/')+path.strip('/')+('/' if path.strip('/') else '')
def arrow(): return '<span class="arrow" aria-hidden="true">↗</span>'
def link(url,label,cls='text-link',extra=''): return f'<a class="{cls}" href="{e(url,quote=True)}" {extra}>{label}{arrow()}</a>'
def ul(items,cls=''): return f'<ul class="{cls}">'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'
def write(path,body,lang,title,desc,other=None,index=True,schema=None):
    url=BASE+path
    if other is None:
        pairs={'missions':'assignments','livrables':'deliverables','ia':'ai','abonnes':'members','profil':'profile','mentions-legales':'legal','confidentialite':'privacy'}
        parts=path.strip('/').split('/')
        if lang=='fr':
            parts=parts[1:]
            if parts:parts[0]=pairs.get(parts[0],parts[0])
            other='/'+('/'.join(parts)+'/ ' if parts else '')
        else:
            inverse={v:k for k,v in pairs.items()}
            if parts and parts[0]:parts[0]=inverse.get(parts[0],parts[0])
            other='/fr/'+('/'.join(parts)+'/' if parts and parts[0] else '')
        other=other.replace('/ ','/')
        other=other.replace('/publications/merci/','/publications/thank-you/') if lang=='fr' else other.replace('/publications/thank-you/','/publications/merci/')
    otherlang='en' if lang=='fr' else 'fr'
    alt=f'<link rel="alternate" hreflang="{otherlang}" href="{BASE+other}">' if other else ''
    default=BASE+(path if lang=='en' else other) if other else url
    graph=[{'@type':'WebPage','@id':url+'#webpage','url':url,'name':unescape(title),'description':unescape(desc),'inLanguage':lang,'isPartOf':{'@id':BASE+'/#website'}},
           {'@type':'WebSite','@id':BASE+'/#website','name':'Xavier Advisory','url':BASE+'/'},
           {'@type':'Person','@id':BASE+'/#person','name':'Xavier Robitaille','url':BASE+href(lang,'profil' if lang=='fr' else 'profile'),'sameAs':['https://www.linkedin.com/in/xrobitaille/'],'jobTitle':t(lang,'Consultant métier en assurance, finance et investissement','Insurance, Finance and Investment Business Consultant'),'knowsAbout':['Investment accounting','Insurance technical accounting','Financial and regulatory reporting','Investment management platforms','IFRS 9','IFRS 17','Solvency II','Programme Management','Generative AI']}]
    if schema: graph.append(schema)
    canonical=f'<link rel="canonical" href="{url}"><link rel="alternate" hreflang="{lang}" href="{url}">{alt}<link rel="alternate" hreflang="x-default" href="{default}">'
    ld=json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</','<\\/')
    full=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{e(desc,quote=True)}">{canonical}<meta name="robots" content="{'index,follow' if index else 'noindex,follow'}"><meta name="theme-color" content="#0B1530"><meta property="og:type" content="website"><meta property="og:title" content="{e(unescape(title),quote=True)}"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/brand_assets/og-image.jpg"><meta property="og:locale" content="{'fr_FR' if lang=='fr' else 'en_GB'}"><meta property="og:site_name" content="Xavier Advisory"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/inter-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/eb-garamond-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/advisory.css?v=20261016"><script type="application/ld+json">{ld}</script><script defer src="/assets/advisory.js?v=20261016"></script></head><body><a class="skip" href="#main">{t(lang,'Aller au contenu','Skip to content')}</a>{nav(lang,path,other)}<main id="main">{body}</main>{contact(lang)}{footer(lang)}{consent(lang)}</body></html>'''
    p=OUT/path.strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(full,encoding='utf-8')
    BUILT[path]=dict(lang=lang,index=index,title=title)

def logo(lang,inverse=False):
    return f'<a class="logo" href="{href(lang)}" aria-label="Xavier Advisory, {t(lang,"accueil","home")}"><img src="/assets/logo{"-inverse" if inverse else ""}.svg" width="220" height="60" alt="Xavier Advisory"></a>'
def nav(lang,path,other):
    links=[(href(lang)+'#expertise','Expertise'),(href(lang,'missions' if lang=='fr' else 'assignments'),t(lang,'Missions','Assignments')),(href(lang,'livrables' if lang=='fr' else 'deliverables'),t(lang,'Livrables','Deliverables')),(href(lang,'ia' if lang=='fr' else 'ai'),t(lang,'IA & Finance','AI & Finance')),(href(lang,'insights'),t(lang,'Analyses','Insights'))]
    items=''.join(f'<a href="{u}"'+(' aria-current="page"' if path==u else '')+f'>{s}</a>' for u,s in links)
    switch=f'<div class="language"><a href="{path if lang=="fr" else other}" lang="fr" hreflang="fr" {"aria-current=page" if lang=="fr" else ""}>FR</a><span>/</span><a href="{path if lang=="en" else other}" lang="en" hreflang="en" {"aria-current=page" if lang=="en" else ""}>EN</a></div>' if other else ''
    return f'''<header class="header"><div class="header-inner">{logo(lang)}<nav class="nav" id="navigation" aria-label="{t(lang,'Navigation principale','Main navigation')}">{items}<a class="member-link" href="{href(lang,'abonnes' if lang=='fr' else 'members')}">{t(lang,'Espace abonnés','Members')}</a><a class="button small" href="{href(lang)}#contact">{t(lang,'Échanger','Get in touch')}</a></nav>{switch}<button class="menu-toggle" aria-label="{t(lang,'Ouvrir le menu','Open menu')}" aria-expanded="false" aria-controls="navigation"><span></span><span></span></button></div></header>'''
def contact(lang):
    return f'''<section class="contact dark" id="contact"><div class="wrap contact-grid"><div><div class="kicker">{t(lang,'Votre prochaine mission','Your next assignment')}</div><h2>{t(lang,'Parlons de ce que vous devez livrer.','Let’s discuss what you need to deliver.')}</h2><p>{t(lang,'Un programme à cadrer, une clôture à améliorer, un système à déployer ou une fonction Finance à prendre en charge. Échangeons sur votre besoin et sur les modalités d’intervention.','A programme to scope, a close to improve, a system to implement or a Finance function to lead. Let’s discuss your requirements and the assignment.')}</p><div class="actions">{link('https://calendly.com/xrobitaille/1h',t(lang,'Réserver un échange','Book a conversation'),'button gold','data-umami-event="calendly" target="_blank" rel="noopener"')}{link('mailto:xro@xavier-robitaille.com',t(lang,'Écrire à Xavier','Email Xavier'),'button outline','data-umami-event="email"')}</div></div><div class="contact-details"><a href="mailto:xro@xavier-robitaille.com">xro@xavier-robitaille.com</a><a href="tel:+33664890943">+33 6 64 89 09 43</a><a href="https://www.linkedin.com/in/xrobitaille/" target="_blank" rel="noopener" data-umami-event="linkedin">LinkedIn · Xavier Robitaille ↗</a><small>{t(lang,'Basé à Paris. France et international.<br>Interventions en français et en anglais.','Based in Paris. France and international assignments.<br>Delivery in French and English.')}</small></div></div></section>'''
def footer(lang):
    links=[(href(lang,'profil' if lang=='fr' else 'profile'),t(lang,'Profil','Profile')),(href(lang,'publications'),'Actuarius'),(href(lang,'formation'),t(lang,'Formation','Training')),(href(lang,'mentions-legales' if lang=='fr' else 'legal'),t(lang,'Mentions légales','Legal notice')),(href(lang,'confidentialite' if lang=='fr' else 'privacy'),t(lang,'Confidentialité','Privacy'))]
    return f'<footer class="footer"><div class="wrap footer-grid">{logo(lang,True)}<div class="footer-links">'+''.join(f'<a href="{u}">{s}</a>' for u,s in links)+f'<button type="button" data-consent-settings style="border:0;background:none;color:inherit;font:inherit;cursor:pointer;padding:0">{t(lang,"Préférences d’audience","Analytics preferences")}</button></div><span>© 2026 Xavier Advisory</span></div></footer>'
def consent(lang):
    return f'''<aside class="consent" id="consent" aria-label="{t(lang,'Mesure d’audience','Analytics preferences')}" hidden><p>{t(lang,'M’autorisez-vous à mesurer la fréquentation et les clics sur ce site avec Umami ? Vous pouvez refuser et modifier votre choix à tout moment.','May I measure visits and clicks on this website with Umami? You can decline and change your choice at any time.')}</p><div class="consent-actions"><button class="button" data-consent="no">{t(lang,'Refuser','Decline')}</button><button class="button outline" data-consent="yes">{t(lang,'Accepter','Accept')}</button><a href="{href(lang,'confidentialite' if lang=='fr' else 'privacy')}">{t(lang,'En savoir plus','Learn more')}</a></div></aside>'''
def hero(lang,title,intro,kicker='',crumb=True):
    return f'<header class="page-hero"><div class="wrap">'+(f'<div class="breadcrumb"><a href="{href(lang)}">{t(lang,"Accueil","Home")}</a><span>/</span><span>{kicker}</span></div>' if crumb else '')+f'<h1>{title}</h1><p class="intro">{intro}</p></div></header>'
def section_head(title,body='',more=''):
    return f'<div class="section-head"><h2>{title}</h2>'+ (f'<p>{body}</p>' if body else '')+more+'</div>'
def case_card(c,lang):
    d=c[lang];url=href(lang,('missions/' if lang=='fr' else 'assignments/')+c['slug'])
    return f'<a class="case-card" href="{url}" data-tags="{" ".join(c["tags"])}" data-search="{e((c["name"][lang]+" "+d["title"]+" "+d["summary"]).lower(),quote=True)}"><div class="case-meta"><strong>{c["name"][lang]}</strong><span>{c["period"]}</span></div><h3>{d["title"]}</h3><p>{d["summary"]}</p><div class="case-bottom"><span>{t(lang,"Lire le retour d’expérience","Read the case study")}</span>{arrow()}</div></a>'
def domain_cards(lang):
    glyph='<svg class="domain-glyph" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M2 16h28M16 2v28M6 6l20 20M6 26L26 6" stroke="currentColor" stroke-width="1"/><circle cx="16" cy="16" r="7" stroke="currentColor" fill="white"/></svg>'
    return '<div class="expertise-grid">'+''.join(f'<article class="expertise-item">{glyph}<h3>{t(lang,x[2],x[3])}</h3><p>{t(lang,x[4],x[5])}</p>{link(href(lang,"ia" if lang=="fr" else "ai") if x[0]=="ai" else href(lang,"expertise/"+x[1]),t(lang,"Compétences et réalisations","Skills and experience"))}</article>' for x in DOMAINS)+'</div>'
def resources(lang,member=False):
    return '<div class="resources">'+''.join(f'''<article class="card-resource"><span class="resource-kind">{t(lang,'Modèle original · Excel éditable','Original template · Editable Excel')}</span><h3>{t(lang,r[1],r[2])}</h3><p>{t(lang,r[3],r[4])}</p>{f'<button class="button outline small" data-download="{r[0]}">{t(lang,"Télécharger le modèle","Download template")} ↓</button>' if member else link(href(lang,'abonnes' if lang=='fr' else 'members'),t(lang,'Accéder au modèle','Get the template'),'button outline small')}</article>''' for r in RESOURCES)+'</div>'

def home(lang):
    body=f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><div class="kicker">Xavier Robitaille · {t(lang,'Consultant métier indépendant','Independent business consultant')}</div><h1>{t(lang,'Consultant Expert en <em>Assurance, Finance, Investissement &amp; Gestion de Projets</em>','Senior Advisory Uniting <em>Insurance, Finance, Investment &amp; Project Management Expertise</em>')}</h1><p class="intro">{t(lang,'Consultant indépendant basé à Paris. 25 ans dans l’assurance et la gestion d’actifs. Formation actuarielle, qualification comptable, expertise projet, ESCP. Un profil qui couvre la totalité des métiers du chiffre d’une compagnie d’assurance et le management de programmes complexes.','Independent consultant based in Paris. 25 years in insurance and asset management. Actuarial training, an accounting qualification, project expertise and ESCP. A profile covering the full range of financial disciplines within an insurance company and the management of complex programmes.')}</p><div class="actions">{link(href(lang,'missions' if lang=='fr' else 'assignments'),t(lang,'Voir mes réalisations','Explore my work'),'button')}{link('#contact',t(lang,'Parlons de votre besoin','Discuss your requirements'),'button outline')}</div></div><div class="hero-visual"><img class="hero-portrait" src="/brand_assets/xavier-robitaille-portrait.webp" width="840" height="1120" alt="Xavier Robitaille" fetchpriority="high"><div class="hero-caption"><div><strong>Xavier Robitaille</strong>{t(lang,'Conseil métier · Projets · Management de transition','Business advisory · Projects · Interim management')}</div></div></div></div></section>
    <div class="trust" id="clients"><div class="wrap"><p>{t(lang,'Mes clients','My clients')}</p><div class="trust-list"><span>{t(lang,'Assureurs IARD','P&C insurers')}</span><span>{t(lang,'Assureurs Vie','Life insurers')}</span><span>{t(lang,'Réassureurs','Reinsurers')}</span><span>{t(lang,'Gestionnaires d’actifs','Asset managers')}</span><span>{t(lang,'Éditeurs de logiciels','Software vendors')}</span></div></div></div>
    <section class="section" id="profile"><div class="wrap cross-grid"><div class="cross-copy"><div class="kicker">{t(lang,'Ma particularité','What I bring')}</div><h2>{t(lang,'La complémentarité d’une expertise technique, d’expériences opérationnelles et de la conduite de projets complexes.','Technical expertise, operational experience and the management of complex projects.')}</h2><p>{t(lang,'Mon parcours réunit audit financier, management d’équipes, production comptable, financière ou réglementaire, accompagnement des évolutions normatives. Ma connaissance des outils de place et la gestion de projet, côté client ou éditeur, complètent cette expérience Métier.','My background combines financial audit, team management, accounting operations, financial and regulatory reporting, and the implementation of accounting and regulatory changes. My knowledge of industry platforms and my project management experience, on both the client and software vendor side, complement this business expertise.')}</p>{link(href(lang,'profil' if lang=='fr' else 'profile'),t(lang,'Mon parcours en détail','My background in detail'))}</div><div class="cross-panel"><div class="cross-row"><strong>{t(lang,'Comptabilité & provisionnement','Accounting & reserving')}</strong><p>{t(lang,'Schémas comptables French GAAP et IFRS, provisionnement, consolidation et communication financière, états réglementaires.','French GAAP and IFRS accounting schemes, reserving, consolidation and financial disclosures, regulatory reporting.')}</p></div><div class="cross-row"><strong>{t(lang,'Outils de place et data management','Industry platforms and data management')}</strong><p>SimCorp Dimension, Clearwater Analytics, Bloomberg, SAP S/4HANA, Power BI. {t(lang,'Automatisation du traitement des données par l’utilisation de l’IA.','AI-assisted automation of data processing.')}</p></div><div class="cross-row"><strong>{t(lang,'Maîtrise d’ouvrage et Gestion de projets','Business analysis and project management')}</strong><div><p><b>{t(lang,'MOA :','Business analysis:')}</b> {t(lang,'Expressions de besoins, sélection, spécifications fonctionnelles, recettes, migrations, change management.','Requirements, solution selection, functional specifications, acceptance testing, migrations and change management.')}</p><p><b>{t(lang,'PMO :','PMO:')}</b> {t(lang,'Planification, lotissement, RACI, suivi d’avancement, relations Sponsors et CxO.','Planning, work packages, RACI, progress tracking, sponsor and CxO relations.')}</p></div></div><div class="cross-row"><strong>{t(lang,'Gestion d’actifs','Asset management')}</strong><p>{t(lang,'Back et Middle Office titres, parfaite maîtrise d’IFRS 9 (bucketisation, test SPPI, ECL), comptabilisation des opérations de couverture, des repos et des produits structurés.','Investment Back and Middle Office, expert command of IFRS 9 (classification, SPPI testing, ECL), accounting for hedging transactions, repos and structured products.')}</p></div></div></div></section>
    <section class="section white" id="expertise"><div class="wrap">{section_head(t(lang,'Typologie des missions que je peux réaliser pour vous.','Types of assignments I can undertake for you.'),t(lang,'Des compétences reliées à des missions et à des livrables concrets.','Skills connected to assignments and specific deliverables.'))}{domain_cards(lang)}</div></section>
    <section class="section" id="approach"><div class="wrap">{section_head(t(lang,'Des résultats issus du terrain.','Results from actual assignments.'),'',link(href(lang,'missions' if lang=='fr' else 'assignments'),t(lang,'Toutes les missions','All assignments')))}<div class="case-list">{''.join(case_card(c,lang) for c in CASES[:2])}</div><div class="proof-strip"><div><strong>{t(lang,'J+4 → J+2','D+4 → D+2')}</strong><p>{t(lang,"Éditeur de logiciels de gestion d’actifs","Investment management software provider")} · {t(lang,'Clôture investissements','Investment close')}</p></div><div><strong>{t(lang,'J+5 → J+3','D+5 → D+3')}</strong><p>{t(lang,"Assureur crédit","Credit insurer")} · {t(lang,'Comptabilité des placements','Investment accounting')}</p></div></div></div></section>
    <section class="section dark"><div class="wrap ai-layout"><div><div class="kicker">{t(lang,'IA appliquée à la Finance','AI applied to Finance')}</div><h2>{t(lang,'Des usages adaptés à votre politique de protection des données, à vos modes de travail et toujours sous supervision humaine.','Use cases adapted to your data protection policy and ways of working, always under human supervision.')}</h2><p>{t(lang,'Rapprochements, analyse d’écarts, documentation et automatisation. Je combine ma pratique de la production financière avec l’utilisation d’agents IA dans mon activité de conseil et d’édition.','Reconciliations, exception analysis, documentation and automation. I combine financial production experience with AI agents used in my consulting and publishing activities.')}</p><div class="actions">{link(href(lang,'ia' if lang=='fr' else 'ai'),t(lang,'Voir les usages et la démonstration','Explore use cases and a demonstration'),'button gold')}</div></div><div class="ai-console" aria-label="{t(lang,'Exemple de processus contrôlé','Example of a controlled process')}"><div class="console-head">{t(lang,'Rapprochement placements','Investment reconciliation')}<span><i></i><i></i><i></i></span></div><div class="flow"><div>{t(lang,'Données sources','Source data')}<br>Front Office / Back Office</div><span>→</span><div>{t(lang,'Règles de contrôle','Control rules')}<br>{t(lang,'Positions, prix, devises','Positions, prices, currencies')}</div></div><div class="check">{t(lang,'Calcul reproductible','Reproducible calculation')}<span>✓</span></div><div class="check">{t(lang,'Écart documenté','Documented exception')}<span>✓</span></div><div class="check">{t(lang,'Validation humaine','Human review')}<span>✓</span></div></div></div></section>
    <section class="section"><div class="wrap">{section_head(t(lang,'Une palette d’outils éprouvés pour répondre à vos besoins.','Proven tools to meet your needs.'),t(lang,'Des exemples et des modèles originaux, sur données fictives ou sous forme de trames à adapter.','Original examples and templates, using fictional data or structures you can adapt.'),link(href(lang,'livrables' if lang=='fr' else 'deliverables'),t(lang,'Explorer les livrables','Explore deliverables')))}{resources(lang)}</div></section>
    {publishing(lang,compact=True)}'''
    write(href(lang),body,lang,t(lang,'Conseil et management de transition en assurance et finance | Xavier Advisory','Insurance and Finance Business Advisory & Interim Management | Xavier Advisory'),t(lang,'Xavier Robitaille, consultant métier indépendant : conseil, management de transition, comptabilité, reporting et gestion de projets en assurance, finance et gestion d’actifs.','Xavier Robitaille, independent business consultant: advisory, interim management, accounting, reporting and project management in insurance, finance and asset management.'))

def missions(lang):
    labels=[('all',t(lang,'Toutes','All'))]+[(x[0],t(lang,x[2],x[3])) for x in DOMAINS]
    body=hero(lang,t(lang,'Des missions qui relient les compétences.','Assignments that connect the disciplines.'),t(lang,'Chaque retour d’expérience précise le contexte, mon rôle, les travaux réalisés et les livrables. Les résultats présentés sont ceux de missions identifiées.','Each case study explains the context, my role, the work and the deliverables. Results relate to identified assignments.'),t(lang,'Missions','Assignments'))
    body+=f'<section class="section"><div class="wrap"><div class="searchbox"><label for="case-search">{t(lang,"Rechercher un besoin, une compétence ou un type d’organisation","Search by need, skill or organisation type")}</label><input id="case-search" type="search" placeholder="{t(lang,"Ex. : clôture, IFRS 9, bancassureur…","E.g. close, IFRS 9, bancassurer…")}"></div><div class="filters" aria-label="{t(lang,"Filtrer les missions","Filter assignments")}">'+''.join(f'<button class="filter" data-filter="{k}" aria-pressed="{str(k=="all").lower()}">{v}</button>' for k,v in labels)+f'</div><p class="result-count" aria-live="polite" id="case-count"></p><div class="case-list" id="case-list">'+''.join(case_card(c,lang) for c in CASES)+f'<p class="empty" hidden>{t(lang,"Aucun résultat. Essayez un autre terme ou une autre compétence.","No results. Try a different search or skill.")}</p></div></div></section>'
    write(href(lang,'missions' if lang=='fr' else 'assignments'),body,lang,t(lang,'Missions & retours d’expérience | Xavier Advisory','Assignments & case studies | Xavier Advisory'),t(lang,'Retours d’expérience anonymisés en conseil métier, comptabilité, reporting, direction de projet et management de transition en assurance.','Anonymous case studies in business advisory, accounting, reporting, project leadership and interim management in insurance.'))
    for c in CASES:
        d=c[lang]
        body=hero(lang,d['title'],d['summary'],c['name'][lang])
        body+=f'<section class="section"><div class="wrap two-col"><div class="prose"><div class="kicker">{c["name"][lang]} · {c["period"]}</div><h2>{t(lang,"Le contexte","Context")}</h2><p>{d["context"]}</p><h2>{t(lang,"Mon intervention","My work")}</h2>{ul(d["actions"])}</div><aside class="aside"><h3>{t(lang,"Responsabilité","Role")}</h3><p>{d["role"]}</p><div class="tag-list">'+''.join(f'<span class="tag">{t(lang,x[2],x[3])}</span>' for x in DOMAINS if x[0] in c['tags'])+f'</div>{link(href(lang,"livrables" if lang=="fr" else "deliverables"),t(lang,"Voir des exemples de livrables","See sample deliverables"))}</aside></div></section><section class="section white"><div class="wrap two-col"><div><h2>{t(lang,"Résultats et réalisations","Results and work delivered")}</h2>'+''.join(f'<div class="outcome">{s}</div>' for s in d['results'])+f'</div><div class="prose"><h2>{t(lang,"Types de livrables","Deliverable types")}</h2>{ul(d["outputs"],"deliver-list")}<p class="subtle">{t(lang,"Les exemples de la bibliothèque sont des modèles originaux. Les documents clients restent confidentiels.","Library examples are original templates. Client documents remain confidential.")}</p></div></div></section><section class="section"><div class="wrap">{link(href(lang,"missions" if lang=="fr" else "assignments"),t(lang,"Revenir aux missions","Back to assignments"))}</div></section>'
        write(href(lang,('missions/' if lang=='fr' else 'assignments/')+c['slug']),body,lang,e(c['name'][lang]+' : '+d['title']+' | Xavier Advisory'),d['summary'])

def demo(lang):
    return f'''<div class="demo" id="reconciliation-demo" data-lang="{lang}"><h3>{t(lang,'Essayer un rapprochement de positions','Try a position reconciliation')}</h3><p class="demo-note">{t(lang,'Jeu de données entièrement fictif. Les calculs et commentaires ci-dessous suivent des règles déterministes, exécutées dans votre navigateur.','Entirely fictional data. The calculations and comments below use deterministic rules, executed in your browser.')}</p><div class="demo-controls"><div class="field"><label for="demo-scenario">{t(lang,'Scénario','Scenario')}</label><select id="demo-scenario"><option value="mixed">{t(lang,'Écarts de quantité et de prix','Quantity and price exceptions')}</option><option value="clean">{t(lang,'Positions rapprochées','Reconciled positions')}</option><option value="missing">{t(lang,'Position absente chez le dépositaire','Missing custodian position')}</option></select></div><div class="field"><label for="demo-tolerance">{t(lang,'Seuil d’écart de prix (%)','Price tolerance (%)')}</label><input type="number" id="demo-tolerance" min="0" max="10" step="0.1" value="0.5"></div></div><div class="table-scroll"><table class="data-table"><caption class="subtle">{t(lang,'Comparaison du Back Office et du dépositaire','Back Office and custodian comparison')}</caption><thead><tr><th>{t(lang,'Instrument fictif','Fictional instrument')}</th><th>{t(lang,'Quantité BO / dépositaire','BO / custodian quantity')}</th><th>{t(lang,'Prix BO / dépositaire','BO / custodian price')}</th><th>{t(lang,'Contrôle','Check')}</th></tr></thead><tbody id="demo-rows"></tbody></table></div><div class="demo-output" id="demo-output" aria-live="polite"></div><p class="demo-note">{t(lang,'Le commentaire propose un contrôle à effectuer ; il n’établit pas la cause de l’écart. Dans un projet IA, cette étape peut préparer une revue humaine à partir de sources autorisées.','The comment suggests a check; it does not establish the cause of an exception. In an AI project, this step can prepare human review using authorised sources.')}</p></div>'''

def ai(lang):
    body=hero(lang,t(lang,'L’IA appliquée aux travaux Finance.','AI applied to Finance work.'),t(lang,'Concevoir un usage utile, organiser les données, vérifier les résultats et garder la responsabilité de la décision. Mes cas d’usage partent des contraintes de la production financière.','Choose a useful task, organise the data, verify the output and retain responsibility for the decision. My use cases start with financial production requirements.'),t(lang,'IA & Finance','AI & Finance'))
    rows=[('Rapprochements & contrôles','Reconciliations & controls','Comparer les sources, isoler les écarts et préparer leur analyse. La règle de rapprochement et les montants restent calculables et vérifiables.','Compare sources, isolate exceptions and prepare analysis. Matching rules and amounts remain calculable and verifiable.'),('Documentation de production','Production documentation','Préparer procédures, scénarios de recette et notes de synthèse à partir de sources identifiées, avec relecture métier.','Draft procedures, test scenarios and briefing notes from identified sources, with business review.'),('Agents pour le conseil et l’édition','Agents for consulting and publishing','J’utilise des agents Claude et GPT pour préparer et contrôler des documents, organiser la recherche et automatiser des traitements récurrents.','I use Claude and GPT agents to prepare and review documents, organise research and automate recurring processing.'),('Cadrage & formation des équipes','Scoping & team training','Définir un premier périmètre, les données autorisées, les critères de validation et les responsabilités. Former les équipes sur leurs propres cas.','Define an initial scope, permitted data, acceptance criteria and responsibilities. Train teams on their own cases.')]
    body+=f'<section class="section"><div class="wrap cross-grid"><div><h2>{t(lang,"Une pratique métier, complétée par l’IA.","Business experience, supported by AI.")}</h2><p class="intro">{t(lang,"Lors d’une mission auprès d’un éditeur de logiciels de gestion d’actifs, les travaux incluaient les rapprochements et contrôles assistés par l’IA de la solution. Dans ma propre activité, je développe des usages d’agents pour le conseil et l’édition.","During an assignment for an investment management software provider, the work included reconciliations and controls assisted by the solution’s AI. In my own practice, I develop agent workflows for consulting and publishing.")}</p><div class="qualifications"><div class="qualification">Generative AI Primer · Vanderbilt University</div><div class="qualification">GenAI for Account Executives · Yale University</div><div class="qualification">Claude Platform 101 · Claude Code 101<small>Anthropic · 2026</small></div></div></div><div class="feature-rows">'+''.join(f'<details {"open" if i==0 else ""}><summary>{t(lang,r[0],r[1])}</summary><p>{t(lang,r[2],r[3])}</p></details>' for i,r in enumerate(rows))+f'</div></div></section><section class="section white"><div class="wrap">{section_head(t(lang,"Un exemple que vous pouvez manipuler.","An example you can try."),t(lang,"Rapprochement, seuil de contrôle et orientation de l’analyse : les étapes sont visibles.","Reconciliation, tolerance and review suggestions: each step is visible."))}{demo(lang)}</div></section><section class="section"><div class="wrap two-col"><div><h2>{t(lang,"Cadrer votre premier usage.","Scope your first use case.")}</h2><p class="intro">{t(lang,"La grille abonnés aide à décrire le travail, les données, les contrôles et les conditions d’exploitation.","The member template helps describe the task, data, controls and operating requirements.")}</p><div class="actions">{link(href(lang,"abonnes" if lang=="fr" else "members"),t(lang,"Accéder à la grille","Get the assessment template"),"button")}{link(href(lang,"formation"),t(lang,"Voir les formations","Explore training"))}</div></div><div class="prose"><h3>{t(lang,"Les questions à résoudre dès le cadrage","Questions to resolve at scoping")}</h3>{ul(t(lang,['Quel travail précis faut-il produire ?','Quelles données peuvent être utilisées, dans quel environnement ?','Quels contrôles établissent que le résultat est exploitable ?','Qui valide et qui traite les exceptions ?'],['What specific work needs to be produced?','Which data can be used, and in which environment?','Which checks establish that the result is usable?','Who approves the result and handles exceptions?']))}</div></div></section>'
    write(href(lang,'ia' if lang=='fr' else 'ai'),body,lang,t(lang,'IA pour la Finance : contrôles, automatisation & formation | Xavier Advisory','AI for Finance: controls, automation & training | Xavier Advisory'),t(lang,'Usages de l’IA en finance et assurance : rapprochements, analyse d’écarts, documentation et agents. Démonstration interactive et grille de cadrage.','AI use cases for insurance Finance: reconciliations, exception analysis, documentation and agents. Interactive demonstration and assessment template.'))

def deliverables(lang):
    body=hero(lang,t(lang,'Des livrables que vous pouvez examiner.','Deliverables you can examine.'),t(lang,'La qualité d’une intervention se voit aussi dans ce qu’elle laisse aux équipes. Voici les formats que je peux produire et des modèles originaux à adapter à votre situation.','The value of an assignment also depends on what it leaves with the team. Explore the formats I can produce and original templates you can adapt.'),t(lang,'Livrables','Deliverables'))
    items=t(lang,[('Cadrage & gouvernance','Note de cadrage, feuille de route, registre des risques et dépendances, note de décision pour comité.','programme-placements-editeur'),('Conception métier & données','Expression des besoins, spécifications fonctionnelles, schémas comptables, dictionnaire de données et mappings.','deploiement-placements-reassureur'),('Recette & bascule','Matrice de recette, scénarios par instrument et référentiel, rapprochements de migration, plan de bascule et suivi des anomalies.','projet-placements-bancassureur'),('Production & contrôle','Calendrier de clôture, modèle ECL, contrôles de rapprochement, tableau de bord et procédures de production.','production-placements-assureur-credit')],[('Scoping & governance','Scoping paper, programme plan, risk and dependency register, committee decision paper.','programme-placements-editeur'),('Business & data design','Business requirements, functional specifications, accounting schemes, data dictionary and mappings.','deploiement-placements-reassureur'),('Testing & cutover','Test matrix, scenarios by instrument and accounting framework, migration reconciliations, cutover plan and issue tracking.','projet-placements-bancassureur'),('Production & controls','Close calendar, ECL model, reconciliation controls, dashboard and operating procedures.','production-placements-assureur-credit')])
    body+='<section class="section"><div class="wrap"><div class="case-list">'+''.join(f'<article class="card-resource"><h3>{a}</h3><p>{b}</p>{link(href(lang,("missions/" if lang=="fr" else "assignments/")+slug),t(lang,"Voir une mission associée","See a related assignment"))}</article>' for a,b,slug in items)+f'</div></div></section><section class="section white"><div class="wrap">{section_head(t(lang,"Examiner un contrôle de rapprochement.","Examine a reconciliation control."))}{demo(lang)}</div></section><section class="section"><div class="wrap">{section_head(t(lang,"Des trames pour vos propres travaux.","Templates for your own work."),t(lang,"Gratuit sur inscription. Modèles Excel éditables, disponibles en français et en anglais.","Free registration. Editable Excel templates, available in French and English."))}{resources(lang)}<p class="subtle" style="margin-top:25px">{t(lang,"Ces modèles ont été créés pour cette bibliothèque. Ils illustrent les types de livrables et ne reproduisent aucun dossier client.","These templates were created for this library. They illustrate deliverable types and do not reproduce client files.")}</p></div></section>'
    write(href(lang,'livrables' if lang=='fr' else 'deliverables'),body,lang,t(lang,'Exemples de livrables Finance, PMO & systèmes | Xavier Advisory','Finance, PMO & systems deliverable examples | Xavier Advisory'),t(lang,'Modèles de clôture, matrice de recette, registre de programme et grille IA. Exemples interactifs et téléchargements réservés aux abonnés.','Close checklist, test matrix, programme register and AI assessment. Interactive examples and member downloads.'))

