        related=[c for c in CASES if domain[0] in c['tags']]
        clean=[f'<strong>{a}.</strong> {b}' for a,b in DETAILS[domain[0]][lang]]
        body=hero(lang,title,intro,'Expertise')+f'<section class="section"><div class="wrap cross-grid"><div><h2>{t(lang,"Ce que je peux livrer","What I can deliver")}</h2><div class="prose">{ul(clean,"deliver-list")}</div></div><aside class="aside"><h3>{t(lang,"Une intervention reliée à votre production","An assignment connected to your production")}</h3><p>{t(lang,"Le cadrage précise le périmètre, les responsabilités, les sources, les contrôles et les livrables attendus avec vos équipes.","Scoping establishes responsibilities, data sources, controls and expected deliverables with your teams.")}</p><div class="actions">{link(href(lang,"livrables" if lang=="fr" else "deliverables"),t(lang,"Examiner les livrables","Examine deliverables"))}</div></aside></div></section><section class="section white"><div class="wrap">{section_head(t(lang,"Des missions associées.","Related assignments."))}<div class="case-list">'+''.join(case_card(c,lang) for c in related)+f'</div></div></section>'
        write(href(lang,'expertise/'+slug),body,lang,e(t(lang,'Consultant '+title,title+' consultant')+' | Xavier Advisory'),intro,schema={'@type':'Service','name':title,'serviceType':title,'provider':{'@type':'Person','@id':BASE+'/#person'},'areaServed':['France','Europe','International']})

